using System.IO;
using System.Windows;
using System.Windows.Controls;
using Microsoft.Win32;
namespace DanceStudio;
public sealed partial class MainWindow {
 static string ExportWarningSummary(string folder){try{int bones=0,floats=0;foreach(var path in Directory.EnumerateFiles(folder,"*.verification.json",SearchOption.AllDirectories)){using var doc=System.Text.Json.JsonDocument.Parse(File.ReadAllText(path));bones+=doc.RootElement.GetProperty("warnings").GetArrayLength();if(doc.RootElement.TryGetProperty("floatWarning",out var warning)&&warning.GetBoolean())floats++;}return $"오차 진단 경고: 본 {bones}개, Float {floats}개 보고서. 임계값은 진단용이며 보고서의 시간·원본 디코더 한계를 확인하세요.\n\n";}catch{return "오차 진단 보고서를 직접 확인하세요.\n\n";}}
 string? ChooseMissingRig(string missing){string? selected=null;var dialog=new Window{Owner=this,Title="원본 스켈레톤 파일 없음",Width=660,Height=260,WindowStartupLocation=WindowStartupLocation.CenterOwner};var panel=new StackPanel{Margin=new Thickness(16)};panel.Children.Add(new TextBlock{Text=missing+"\n\n내장 스켈레톤으로 조용히 대체하지 않았습니다. 사용할 스켈레톤을 직접 선택하세요. 본 매핑 검증은 다시 수행됩니다.",TextWrapping=TextWrapping.Wrap});var builtin=new Button{Content="내장 기본 스켈레톤 사용",Margin=new Thickness(0,10,0,10)};builtin.Click+=(_,_)=>{selected=DanceStudio.Rig.BuiltinId;dialog.DialogResult=true;};var custom=new Button{Content="원본 스켈레톤 파일 선택"};custom.Click+=(_,_)=>{var file=new OpenFileDialog{Filter="스켈레톤 HKX|*.hkx"};if(file.ShowDialog(dialog)==true){selected=file.FileName;dialog.DialogResult=true;}};panel.Children.Add(builtin);panel.Children.Add(custom);dialog.Content=panel;dialog.ShowDialog();return selected;}
 void ConfigureVerification(){
  if(busy)return;Stop();var dialog=new Window{Owner=this,Title="출력 오차 진단 설정",Width=520,Height=500,WindowStartupLocation=WindowStartupLocation.CenterOwner};var panel=new StackPanel{Margin=new Thickness(16)};panel.Children.Add(new TextBlock{Text="이 값은 경고 기준이며 정확성의 정답이나 자동 보정값이 아닙니다. 프로젝트와 함께 저장됩니다.",TextWrapping=TextWrapping.Wrap});var boxes=new List<TextBox>();foreach(var item in new[]{("위치 오차 (스켈레톤 좌표 단위)",Project.Verification.PositionWarning),("회전각 오차 (도)",Project.Verification.RotationWarningDegrees),("스케일 벡터 오차",Project.Verification.ScaleWarning),("Float 값 오차",Project.Verification.FloatWarning),("출력 프레임 분할 수 (2~8)",(double)Project.Verification.Subdivisions)}){panel.Children.Add(new TextBlock{Text=item.Item1});var box=new TextBox{Text=item.Item2.ToString(System.Globalization.CultureInfo.InvariantCulture),Margin=new Thickness(0,2,0,8)};panel.Children.Add(box);boxes.Add(box);}var save=new Button{Content="적용"};save.Click+=(_,_)=>{try{double Read(int i)=>double.Parse(boxes[i].Text,System.Globalization.CultureInfo.InvariantCulture);var options=new MotionCheckOptions{PositionWarning=Read(0),RotationWarningDegrees=Read(1),ScaleWarning=Read(2),FloatWarning=Read(3),Subdivisions=int.Parse(boxes[4].Text)};options.Validate();Project.Verification=options;dirty=true;dialog.DialogResult=true;}catch(Exception e){MessageBox.Show(dialog,e.Message,"진단 설정 확인");}};panel.Children.Add(save);dialog.Content=panel;dialog.ShowDialog();
 }
 CameraProposal? cachedProposal;MotionClip? proposalClip;Rig? proposalRig;
 CameraProposal Proposal(){if(CameraClip==null||Rig==null)throw new InvalidOperationException("카메라를 먼저 불러오세요.");if(cachedProposal==null||proposalClip!=CameraClip||proposalRig!=Rig){cachedProposal=CameraAnalysis.Analyze(CameraClip,Rig);proposalClip=CameraClip;proposalRig=Rig;}return cachedProposal;}
 void CameraInfo(){if(CameraClip==null||Rig==null){cameraStatus.Text="카메라 본과 전방축을 확인하세요.";return;}var proposal=Proposal();if(!CameraClip.BoneMap.Contains(Project.CameraBone)){cameraStatus.Text="선택한 카메라 본이 실제 트랙에 없습니다. 직접 다시 선택해야 내보낼 수 있습니다.";return;}cameraStatus.Text=(Project.CameraBoneManual?"본: 사용자 지정. ":"본: 이름 기반 후보, 확인 필요. ")+(Project.CameraForwardManual?"전방축: 사용자 지정 ":"전방축: 미확정 기본값 ")+Project.CameraForward+(proposal.AxisSuggestion is string axis?" · 여러 시점 기준 참고 "+axis+" (자동 적용 안 함)":" · 신뢰할 수 있는 전방축 추천 없음")+". 정적 카메라도 정상 후보입니다.";}

 async Task<MotionClip> LoadMotion(string path,int? bindingIndex=null,string? proof=null,Rig? targetRig=null){
  var rig=targetRig??Rig;
  while(true){MotionClip? candidate=null;try{candidate=await Task.Run(()=>MotionClip.Load(path,bindingIndex,proof));if(rig!=null)candidate.ValidateRig(rig);return candidate;}
   catch(HkxSelectionRequired choice){var window=new Window{Owner=this,Title="HKX 애니메이션 선택",Width=680,Height=260,WindowStartupLocation=WindowStartupLocation.CenterOwner};var panel=new StackPanel{Margin=new Thickness(16)};panel.Children.Add(new TextBlock{Text="재생할 바인딩을 직접 선택하세요. 복수 구성의 출력은 현재 차단됩니다.",TextWrapping=TextWrapping.Wrap});var list=new ComboBox{Margin=new Thickness(0,14,0,14),ItemsSource=choice.Choices.Select(c=>$"바인딩 {c.BindingIndex} / 모션 {c.AnimationIndex} / {c.Type} / {c.Duration:0.###}초 / {c.Tracks}트랙").ToArray(),SelectedIndex=-1};panel.Children.Add(list);var ok=new Button{Content="선택",IsEnabled=false};list.SelectionChanged+=(_,_)=>ok.IsEnabled=list.SelectedIndex>=0;ok.Click+=(_,_)=>window.DialogResult=true;panel.Children.Add(ok);window.Content=panel;if(window.ShowDialog()!=true)throw new OperationCanceledException("HKX 선택 취소");bindingIndex=choice.Choices[list.SelectedIndex].BindingIndex;}
   catch(HkxMappingRequired mapping){if(rig==null)throw;var window=new Window{Owner=this,Title="HKX 매핑 — 스켈레톤 순서 확인",Width=680,Height=310,WindowStartupLocation=WindowStartupLocation.CenterOwner};var panel=new StackPanel{Margin=new Thickness(16)};panel.Children.Add(new TextBlock{Text=Path.GetFileName(path)+"\n\n"+mapping.Message+"\n선택한 스켈레톤 ‘"+rig.Name+"’의 순서와 같은 원본임을 확인한 경우에만 계속하세요. 다른 순서의 파일을 자동 보정하지 않습니다.\n이 확인은 원본 파일과 스켈레톤 구조 지문에 묶여 프로젝트에 저장됩니다.",TextWrapping=TextWrapping.Wrap});var ok=new Button{Content="이 스켈레톤의 순서를 사용",Margin=new Thickness(0,14,0,0)};ok.Click+=(_,_)=>window.DialogResult=true;panel.Children.Add(ok);window.Content=panel;if(window.ShowDialog()!=true)throw new OperationCanceledException("HKX 본 매핑 확인 취소");proof=candidate!.MappingProofFor(rig);}
  }
 }
 async Task DiagnoseHkx()=>await Guard(async()=>{
  var open=new OpenFileDialog{Filter="HKX 및 진단 참조 데이터|*.hkx;*.hkx.reference|모든 파일|*.*",Title="원본을 변경하지 않고 검사할 HKX 선택"};if(open.ShowDialog(this)!=true)return;SetBusy(true,"HKX 구성과 지원 여부를 검사하는 중…");var rig=Rig??await Task.Run(()=>DanceStudio.Rig.Load(DanceStudio.Rig.BuiltinId));var loaded=new[]{Dance,CameraClip}.FirstOrDefault(x=>x!=null&&Path.GetFullPath(x.Path).Equals(Path.GetFullPath(open.FileName),StringComparison.OrdinalIgnoreCase));var report=await Task.Run(()=>HkxDiagnostics.Inspect(open.FileName,rig,loaded?.BindingIndex,loaded?.IdentityRigProof));SetBusy(false,"HKX 진단 완료 · 원본은 변경하지 않았습니다.");
  var dialog=new Window{Owner=this,Title="HKX 진단 — 원본 / 지원 / 변환 / 제한",Width=1000,Height=720,WindowStartupLocation=WindowStartupLocation.CenterOwner};var panel=new DockPanel{Margin=new Thickness(12)};var save=new Button{Content="진단 보고서 JSON 저장",Margin=new Thickness(0,0,0,10)};DockPanel.SetDock(save,Dock.Top);panel.Children.Add(save);var text=new TextBox{Text=report.Json(),IsReadOnly=true,AcceptsReturn=true,TextWrapping=TextWrapping.NoWrap,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,HorizontalScrollBarVisibility=ScrollBarVisibility.Auto};panel.Children.Add(text);save.Click+=(_,_)=>{try{var target=new SaveFileDialog{Filter="HKX 진단 JSON|*.json",FileName=Path.GetFileName(open.FileName)+".diagnostics.json"};if(target.ShowDialog(dialog)!=true)return;if(Path.GetFullPath(target.FileName).Equals(Path.GetFullPath(open.FileName),StringComparison.OrdinalIgnoreCase))throw new IOException("원본 HKX 경로에는 보고서를 저장할 수 없습니다.");SongProject.AtomicWrite(target.FileName,report.Json());}catch(Exception e){MessageBox.Show(dialog,e.Message,"진단 저장 실패");}};dialog.Content=panel;dialog.ShowDialog();
 });
}
